query AdsHeartbeatSep14MorningOrderCounts {
 shop { id name ianaTimezone }
 allNew: ordersCount(query:"created_at:>='2026-09-14T03:00:36Z' created_at:<'2026-09-14T06:59:06Z'",limit:null) { count precision }
 webNonTest: ordersCount(query:"created_at:>='2026-09-14T03:00:36Z' created_at:<'2026-09-14T06:59:06Z' source_name:web test:false",limit:null) { count precision }
 paidWebNonTest: ordersCount(query:"created_at:>='2026-09-14T03:00:36Z' created_at:<'2026-09-14T06:59:06Z' source_name:web test:false financial_status:paid",limit:null) { count precision }
}
